//! Native B04B80/B0F960/B0F9C0 slot target selection. DSP refresh is mandatory.
use crate::{audio_bus_registry::Bus,audio_bus_control_application::{Store,Voice},audio_bus_bank::Error,audio_bus_effects_bank as effects};
#[derive(Debug,Clone,Copy)] pub enum Binding{Primary,VoiceBus(u32)}
#[derive(Debug,Clone)] pub struct Call{pub voice:u32,pub binding:Binding,pub index:u32}
pub trait Refresh{fn refresh(&mut self,reference:u32,voice:&mut Voice,binding:Binding,index:u32)->Result<(),Error>;}
pub fn dispatch(bus:&Bus,store:&mut Store,index:u32,backend:&mut impl Refresh)->Result<Vec<Call>,Error>{if bus.reference==0{return Err(Error::UnresolvedReference);}if bus.word(0)!=0xff1380{return Err(Error::WrongClass);}let mut selected=Vec::new();if bus.word(0x24)==0 && bus.raw[0xc4]&0x80!=0{if let Some(root)=store.roots.iter().find(|v|v.key==[0,0]){if !store.voices.contains_key(&root.voice){return Err(Error::Application(crate::audio_bus_control_application::Error::MissingVoice(root.voice)));}selected.push((root.voice,Binding::Primary));}}else{for &reference in &store.registered{let voice=store.voices.get(&reference).ok_or(Error::Application(crate::audio_bus_control_application::Error::MissingVoice(reference)))?;let pointer=u32::from_le_bytes(voice.raw[0x4d0..0x4d4].try_into().unwrap());let id=if pointer==0{0}else{*store.bus_ids.get(&pointer).ok_or(Error::Application(crate::audio_bus_control_application::Error::MissingBus(pointer)))?};let mode=u32::from_le_bytes(voice.raw[0x4d4..0x4d8].try_into().unwrap());if id==bus.word(8) && mode!=2{selected.push((reference,Binding::VoiceBus(reference)));}}}let mut calls=Vec::new();for(reference,binding)in selected{backend.refresh(reference,store.voices.get_mut(&reference).unwrap(),binding,index)?;calls.push(Call{voice:reference,binding,index});}Ok(calls)}
pub struct Backend<'a,B,R>{pub dependencies:&'a mut B,pub targets:&'a mut Store,pub refresh:&'a mut R,pub calls:Vec<Call>,pub applied:Vec<crate::audio_bus_control_application::Call>}
impl<B:effects::Backend,R:Refresh> effects::Backend for Backend<'_,B,R>{fn allocate(&mut self,n:u32)->Result<Option<effects::Allocation>,Error>{self.dependencies.allocate(n)}fn changed(&mut self,b:&mut Bus,c:&effects::Cache)->Result<(),Error>{self.dependencies.changed(b,c)}fn mask(&mut self,b:&mut Bus,v:u32,m:u32)->Result<(),Error>{self.dependencies.mask(b,v,m)}fn slot(&mut self,b:&mut Bus,i:u32)->Result<(),Error>{self.calls.extend(dispatch(b,self.targets,i,self.refresh)?);Ok(())}fn apply(&mut self,b:&Bus,v:u32,m:u32)->Result<(),Error>{let calls=if b.word(0x24)==0 && b.raw[0xc4]&0x80!=0{self.targets.root(v,m)}else{self.targets.bus(b.word(8),v,m)}.map_err(Error::Application)?;self.applied.extend(calls);Ok(())}}
#[cfg(test)] mod tests{use super::*;use crate::audio_bus_control_application::Root;struct Trace{calls:Vec<serde_json::Value>}impl Refresh for Trace{fn refresh(&mut self,r:u32,_:&mut Voice,b:Binding,i:u32)->Result<(),Error>{self.calls.push(serde_json::json!({"voice":r,"binding":match b{Binding::Primary=>0x14a7aac,Binding::VoiceBus(v)=>v+0x4d0},"index":i}));Ok(())}}
#[test]fn audio_bus_slot_dispatch_matches960_native_cases(){let p:serde_json::Value=serde_json::from_str(include_str!("../../../data/4.20/audio_bus_effect_slot_dispatch_contract.json")).unwrap();assert_eq!(p["case_count"],960);for(case,row)in p["cases"].as_array().unwrap().iter().enumerate(){let bus=Bus{reference:0x30001000,raw:crate::audio_spatial_controls::tests::hex(row["before"].as_str().unwrap())};let mut s=Store::default();s.bus_ids.insert(bus.reference,bus.word(8));for(i,r)in [0x30002000,0x30003000,0x30004000].into_iter().enumerate(){let mut raw=[0xa5;0x500];raw[0x4d0..0x4d4].copy_from_slice(&(if i<2{bus.reference}else{0}).to_le_bytes());raw[0x4d4..0x4d8].copy_from_slice(&(row["modes"][i].as_u64().unwrap() as u32).to_le_bytes());s.voices.insert(r,Voice{raw});s.registered.push(r);s.roots.push(Root{voice:r,key:[if i==row["first_free"].as_u64().unwrap() as usize{0}else{i as u32+1},0]});}let before=s.voices.clone();let mut b=Trace{calls:vec![]};dispatch(&bus,&mut s,row["index"].as_u64().unwrap() as u32,&mut b).unwrap();assert_eq!(serde_json::json!(b.calls),row["calls"],"dispatch {case}");for(r,v)in before{assert_eq!(s.voices[&r].raw,v.raw);}assert_eq!(bus.raw,crate::audio_spatial_controls::tests::hex::<200>(row["after"].as_str().unwrap()));}}}
